<script lang="ts">
 import {onMount} from 'svelte';
 import {fieldValue} from './field-values';
 import QuoteSidebar from './QuoteSidebar.svelte';
 import Icon from './WorkspaceIcon.svelte';
 import QuoteField from './QuoteField.svelte';
 import {pages,activePages,matches,quotesAPI,QuoteError,fieldDefaults,pageValues,type Quote,type Value,type FormPage,type SourceAction} from './quote-model';
 let list=$state<Quote[]>([]), quote=$state<Quote|null>(null), pageID=$state('newquote');
 let values=$state<Record<string,Value>>({}), rows=$state<Record<string,Value>[]>([]);
 let errors=$state<Record<string,string>>({}), error=$state(''), notice=$state(''), busy=$state(false), dirty=$state(false), creating=$state(false), loading=$state(true);
 let search=$state(''), filter=$state('all');
 const drafts=$derived(list.filter(q=>q.status!=='ready_for_rating'));
 const filtered=$derived(list.filter(q=>(filter==='all'||(filter==='draft'?q.status!=='ready_for_rating':q.status==='ready_for_rating'))&&[q.number,q.values['AccountInput.FirstName'],q.values['AccountInput.LastName'],q.values['DwellingInput.Form']].join(' ').toLowerCase().includes(search.toLowerCase())));
 const applicantName=(v:Record<string,Value>)=>[v['AccountInput.FirstName'],v['AccountInput.LastName']].filter(Boolean).join(' ')||'New applicant';
 let request=0; let mounted=false;
 const page=$derived(pages.find(p=>p.id===pageID)??pages[0]);
 const journey=$derived(activePages(values));
 const step=$derived(journey.findIndex(p=>p.id===pageID));
 const fields=$derived(page.fields.filter(f=>!f.hidden&&matches(f.showWhen,values)));
 const groups=$derived([...new Set(fields.map(f=>f.group??'Details'))]);
 const collection=$derived(page.collection&&matches(page.collection.when,values)?page.collection:undefined);
 const eligible=$derived(!!quote&&journey.filter(p=>p.id!=='review').every(p=>quote!.completed.includes(p.id)));
 function leaveOK(){return !dirty||window.confirm('You have unsaved changes. Discard them?');}
 function route(id?:string){history.replaceState(null,'',location.pathname+(id?`#personalhome/quote/${id}`:'#personalhome/newquote'));}
 function install(q:Quote,target=q.current_page){if(!mounted)return;quote=q;values=structuredClone($state.snapshot(q.values));pageID=target;rows=structuredClone($state.snapshot(q.collections[pages.find(p=>p.id===target)?.collection?.key??'']??[]));errors={};error='';dirty=false;creating=false;route(q.id);window.scrollTo({top:0,behavior:'instant'});}
 function showError(e:unknown){error=e instanceof Error?e.message:String(e);errors=e instanceof QuoteError?e.fields:{};notice='';}
 async function load(){const token=++request;loading=true;error='';try{const id=location.hash.match(/^#personalhome\/quote\/([a-f0-9]{24})/)?.[1];if(id){const q=await quotesAPI.get(id);if(token===request)install(q);}else{const items=await quotesAPI.list();if(token===request){list=items;quote=null;creating=false;dirty=false;}}}catch(e){if(token===request)showError(e);}finally{if(token===request)loading=false;}}
 onMount(()=>{mounted=true;void load();const before=(e:BeforeUnloadEvent)=>{if(dirty){e.preventDefault();e.returnValue='';}};const navigation=(e:Event)=>{if(!leaveOK()){e.preventDefault();route(quote?.id);}};const hash=()=>{if(!location.hash.startsWith('#personalhome'))return;if(!leaveOK()){route(quote?.id);return;}void load();};window.addEventListener('beforeunload',before);window.addEventListener('quote-before-leave',navigation);window.addEventListener('hashchange',hash);return()=>{mounted=false;request++;window.removeEventListener('beforeunload',before);window.removeEventListener('quote-before-leave',navigation);window.removeEventListener('hashchange',hash);};});
 function start(){if(!leaveOK())return;quote=null;creating=true;pageID='newquote';values=fieldDefaults(pages.flatMap(p=>p.fields));rows=[];errors={};error='';notice='';dirty=false;route();}
 async function open(q:Quote){if(!leaveOK())return;busy=true;error='';try{install(await quotesAPI.get(q.id));notice='';}catch(e){showError(e);}finally{busy=false;}}
 async function dashboard(){if(!leaveOK())return;dirty=false;route();await load();}
 function change(key:string,value:Value){if(key==='CoverageADwellingInput.Limit'&&typeof value==='number'&&values['DwellingInput.Form']==='HO3'){for(const [dependent,factor] of Object.entries({'CoverageCPersonalPropertyHO3Input.Limit':0.5,'CoverageDLossOfUseInput.Limit':0.2})){if(values[dependent]===null||values[dependent]===undefined||values[dependent]==='')values={...values,[dependent]:Math.round(value*factor)};}if(!values['ReplacementCostDwellingInput.ReplacementCostValue'])values={...values,'ReplacementCostDwellingInput.ReplacementCostValue':value};}values={...values,[key]:value};dirty=true;notice='';errors={...errors,[key]:''};if(key==='DwellingInput.Form'&&value==='HO6')values={...values,'DwellingInput.RoofGeometry':'NA','ReplacementCostDwellingInput.Indicator':false};}
 function updateRow(index:number,key:string,value:Value){rows=rows.map((row,i)=>i===index?{...row,[key]:value}:row);dirty=true;notice='';}
 function addRow(){if(!collection)return;rows=[...rows,fieldDefaults(collection.fields)];dirty=true;notice='';}
 function removeRow(index:number){rows=rows.filter((_,i)=>i!==index);dirty=true;notice='';errors={};}
 function navigate(target:FormPage){if(!quote||!leaveOK())return;install(quote,target.id);notice='';}
 function reachable(target:FormPage){if(!quote)return false;const index=journey.findIndex(p=>p.id===target.id);return journey.slice(0,index).every(p=>quote!.completed.includes(p.id));}
 async function save(advance:boolean){if(busy)return;busy=true;error='';errors={};notice='';try{const saved=quote?await quotesAPI.save(quote,pageID,pageValues(page,values),rows,advance):await quotesAPI.create(pageValues(pages[0],values));install(saved);notice=advance?'Saved. Continue with the next step.':'Draft saved.';}catch(e){showError(e);}finally{busy=false;}}
 async function submit(){if(!quote||busy)return;busy=true;error='';try{const saved=await quotesAPI.submit(quote);install(saved);notice='Application submitted locally. Rating and carrier review are pending.';}catch(e){showError(e);}finally{busy=false;}}
 function copyAddress(){for(const key of ['Address1','Address2','City','State','ZipCode','County'])values={...values,['LocationInput.'+key]:values['AccountInput.'+key]??''};dirty=true;notice='Applicant address copied. Save this page to keep it.';}
 function exportQuote(){if(!quote)return;const url=URL.createObjectURL(new Blob([JSON.stringify(quote,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=quote.number+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 function sourceAction(action:SourceAction){
  if(action.kind==='copy-address')copyAddress();
  if(action.kind==='save-location')void save(false);
  if(action.kind==='cancel-location'&&quote&&leaveOK())install(quote,pageID);
  if(action.kind==='clear-location'){for(const key of ['Address1','Address2','City','State','ZipCode','County'])values={...values,['LocationInput.'+key]:''};dirty=true;notice='Draft location cleared. Save to keep this change, or Cancel to restore the saved location.';}
 }
 const display=(v:Value|undefined)=>v===true?'Yes':v===false?'No':v===null||v===undefined||v===''?'Not provided':String(v);
</script>

<div class="application">
 <div class="breadcrumb">Workspace <span>/</span> Personal Home {#if quote||creating}<span>/</span> {quote?.number??'New quote'}{/if}</div>
 <div class="application-header"><div><span class="eyebrow">PERSONAL HOME · FLORIDA</span><h1>{quote?quote.number:creating?'Start a new quote':'Quote dashboard'}</h1><p class="muted">{quote?'Complete your application one step at a time.':'Create, save and resume PersonalHome applications.'}</p></div><div class="header-actions">{#if quote||creating}<button class="btn" disabled={busy} onclick={dashboard}>All quotes</button>{:else}<button class="btn primary" disabled={loading||busy} onclick={start}>Create quote</button>{/if}{#if quote}<span class="status">{quote.status==='ready_for_rating'?'Awaiting rating':'Draft'}</span>{/if}</div></div>
 {#if error}<div class="message error" role="alert"><b>{error}</b>{#if Object.keys(errors).length}<ul>{#each Object.entries(errors).filter(([,v])=>v) as [key,message]}<li>{pages.flatMap(p=>p.fields).find(f=>f.key===key)?.label??key}: {message}</li>{/each}</ul>{/if}{#if !Object.keys(errors).length}<button class="btn sm" disabled={busy} onclick={()=>{if(leaveOK())void load();}}>Reload saved data</button>{/if}</div>{/if}
 {#if notice}<div class="message success" role="status">{notice}</div>{/if}
 {#if loading}<p role="status">Loading saved quotes…</p>
 {:else if !quote&&!creating}
  <div class="metrics">
   <div class="metric"><span class="metric-icon"><Icon name="file"/></span><div><small>Total applications</small><strong>{list.length}</strong></div></div>
   <div class="metric"><span class="metric-icon"><Icon name="clock"/></span><div><small>Draft applications</small><strong>{drafts.length}</strong></div></div>
   <div class="metric"><span class="metric-icon green"><Icon name="shield"/></span><div><small>Awaiting rating</small><strong>{list.length-drafts.length}</strong></div></div>
  </div>
  <div class="workspace-split">
   <section class="dashboard-card">
    <div class="panel-heading"><div><h2>Quote applications</h2><p class="muted">Your saved applications, ready to pick up where you left off.</p></div><label class="search"><Icon name="search"/><input type="search" aria-label="Search quotes" placeholder="Search quote, applicant…" bind:value={search}/></label></div>
    <div class="filters" aria-label="Filter quotes">{#each [{id:'all',label:'All quotes',count:list.length},{id:'draft',label:'Draft',count:drafts.length},{id:'ready',label:'Awaiting rating',count:list.length-drafts.length}] as tab}<button class:active={filter===tab.id} aria-pressed={filter===tab.id} onclick={()=>filter=tab.id}>{tab.label}<span>{tab.count}</span></button>{/each}</div>
    <div class="quote-table"><table><thead><tr><th>Quote no.</th><th>Applicant</th><th>Policy form</th><th>Effective date</th><th>Status</th><th><span class="sr-only">Action</span></th></tr></thead><tbody>{#each filtered as item}<tr><td><button class="quote-link" disabled={busy} onclick={()=>open(item)}>{item.number}</button></td><td><strong>{applicantName(item.values)}</strong><small>{pages.find(p=>p.id===item.current_page)?.title}</small></td><td><span class="form-badge">{item.values['DwellingInput.Form']}</span></td><td>{item.values['PolicyInput.EffectiveDate']}</td><td><span class="status" class:ready={item.status==='ready_for_rating'}>{item.status==='ready_for_rating'?'Awaiting rating':'Draft'}</span></td><td><button class="open-quote" aria-label={'Open '+item.number} disabled={busy} onclick={()=>open(item)}><Icon name="arrow" size={16}/></button></td></tr>{/each}</tbody></table></div>
    {#if !filtered.length}<div class="empty"><Icon name="home" size={36}/><h3>{list.length?'No matching quotes':'Your next home policy starts here'}</h3><p>{list.length?'Try another search or status filter.':'Create an application to add applicant, property and coverage details.'}</p>{#if !list.length}<button class="btn primary" onclick={start}>Create your first quote</button>{/if}</div>{/if}
    <div class="table-footer">{filtered.length} of {list.length} applications</div>
   </section>
   <aside class="dashboard-aside"><section class="dashboard-card"><div class="panel-heading"><h2><Icon name="clock"/>Continue working</h2></div><div class="queue">{#each drafts.slice(0,4) as item}<button disabled={busy} onclick={()=>open(item)}><div><strong>{applicantName(item.values)}</strong><span class="status">Draft</span></div><p>{item.number} · {item.values['DwellingInput.Form']}</p><div class="queue-footer"><span>{pages.find(p=>p.id===item.current_page)?.title}</span><Icon name="arrow" size={15}/></div></button>{:else}<p class="muted">No draft applications. Start a new quote to begin.</p>{/each}</div></section><section class="dashboard-card guide"><span class="metric-icon"><Icon name="home"/></span><h3>A clear path to your next quote</h3><p>Start with the policy form, add the applicant and property, then review coverages.</p><button class="btn primary" disabled={busy} onclick={start}><Icon name="plus" size={16}/>Create quote</button></section></aside>
  </div>
 {:else}
  <div class="quote-overview">
   <div class="overview-item"><span class="metric-icon"><Icon name="file"/></span><div><small>Quote number</small><strong>{quote?.number??'New application'}</strong></div></div>
   <div class="overview-item"><span class="metric-icon"><Icon name="home"/></span><div><small>Policy form</small><strong>{values['DwellingInput.Form']??'Select a form'}</strong></div></div>
   <div class="overview-item"><span class="metric-icon"><Icon name="user"/></span><div><small>Named insured</small><strong>{applicantName(values)}</strong></div></div>
   <div class="overview-item"><span class="metric-icon"><Icon name="calendar"/></span><div><small>Effective date</small><strong>{values['PolicyInput.EffectiveDate']||'Not selected'}</strong></div></div>
  </div>
   <nav class="quote-nav" aria-label="Quote steps">{#each journey as item,i}<button class:active={pageID===item.id} disabled={busy||!reachable(item)} aria-current={pageID===item.id?'step':undefined} onclick={()=>navigate(item)}><span>{quote?.completed.includes(item.id)?'✓':i+1}</span>{item.title}</button>{/each}</nav>
  <div class="quote-layout">
   <div class="quote-body">
    <section class="form-card"><div class="page-title"><div><span class="eyebrow">STEP {step+1} OF {journey.length}</span><h2>{page.title}</h2></div><span class="save-state">{dirty?'Unsaved changes':quote?'Saved on this computer':'New quote'}</span></div>
     {#if page.notice}<p class="info">{page.notice}</p>{/if}
     {#if pageID==='newquote'}<p class="muted">Start with your product and effective date. A quote number is assigned when you continue.</p>{/if}
     {#if pageID==='dwellinginfo'}<div class="copy-address"><p class="muted">Enter the insured property's address.</p><button class="btn sm" disabled={busy} onclick={copyAddress}>Copy applicant address</button></div>{/if}
     <fieldset disabled={busy}>
      {#each groups as group (pageID+group)}<details class="field-group" open><summary><span class="section-icon"><Icon name={pageID==='dwellingcoverage'?'shield':'file'} size={15}/></span>{group}</summary><div class="field-grid">{#each fields.filter(f=>(f.group??'Details')===group) as field (pageID+field.key)}<QuoteField {field} id={'quote-'+field.key} value={values[field.key]} context={values} invalid={errors[field.key]} onchange={value=>change(field.key,value)}/>{/each}</div></details>{/each}
      {#if collection}<section class="repeat-section"><div class="repeat-heading"><h3>{collection.label}</h3><button data-source-ref={collection.sourceControls?.['collection-add']} type="button" class="btn sm" disabled={rows.length>=100} onclick={addRow}>+ Add {collection.key==='losses'?'loss':collection.key==='priorInsurance'?'prior policy':collection.key==='coapplicants'?'co-applicant':'interest'}</button></div>{#if errors[collection.key]}<p class="field-error">{errors[collection.key]}</p>{/if}{#if !rows.length}<p class="muted">No entries added.</p>{/if}
       {#each rows as row,i}<article class="repeat-row"><div class="repeat-heading"><b>{collection.key==='coapplicants'?'Co-applicant':collection.key==='losses'?'Loss':'Entry'} {i+1}</b><button data-source-ref={collection.sourceControls?.['collection-remove']} class="btn sm ghost" onclick={()=>removeRow(i)}>Remove entry {i+1}</button></div><details open class="row-details"><summary data-source-ref={collection.sourceControls?.['collection-details']}>Details</summary><div class="field-grid">{#each collection.fields.filter(f=>!f.hidden) as field}<QuoteField {field} id={collection.key+'-'+i+'-'+field.key} value={row[field.key]} context={{...values,...row}} rowIndex={i} invalid={errors[collection.key+'.'+i+'.'+field.key]} onchange={value=>updateRow(i,field.key,value)}/>{/each}</div></details></article>{/each}
      </section>{/if}
     </fieldset>
     {#if page.actions?.length}<section class="source-actions"><h3>Page actions</h3><div>{#each page.actions as action}<div class="source-action"><button data-source-ref={action.sourceRefs?.join(' ')} class="btn sm" disabled={busy||action.kind==='unavailable'} onclick={()=>sourceAction(action)}>{action.label}</button>{#if action.kind==='unavailable'}<small>{action.reason}</small>{/if}</div>{/each}</div></section>{/if}
     {#each page.servicePanels??[] as panel}<details class="service-panel"><summary>{panel.title}</summary><p class="muted">{panel.text}</p><dl>{#each panel.fields as label}<dt>{label}</dt><dd>{label==='Insured email address'?values['AccountInput.Email']||'Not provided':'Unavailable — service not connected'}</dd>{/each}</dl><div class="service-buttons">{#each panel.actions as label}<button class="btn sm" disabled>{label}</button>{/each}{#if panel.title==='Subscriber agreement and LPOA'}<button class="btn sm" disabled={busy} onclick={()=>navigate(pages.find(p=>p.id==='account')!)}>Return to Applicant</button>{/if}</div></details>{/each}
     {#if pageID==='summary'||pageID==='review'}
      <div class="rating"><span>Premium</span><strong>Awaiting rating</strong><p>No premium has been calculated. This application does not provide an insurance offer or coverage.</p></div>
      {#if pageID==='review'&&quote?.status==='ready_for_rating'}<div class="message success"><h3>Application captured</h3><p>{quote.number} has been saved and marked ready for rating. A carrier connection is required to obtain a premium and bind coverage.</p><button class="btn" onclick={exportQuote}>Download saved application</button></div>{/if}
      {#each journey.filter(p=>pageID==='review'?!['summary','review'].includes(p.id):['newquote','dwellingcoverage'].includes(p.id)) as section}
       <details class="review-section" open={pageID==='summary'}><summary>{section.title} {#if quote?.completed.includes(section.id)}✓{/if}</summary><dl>{#each section.fields.filter(f=>!f.hidden&&matches(f.showWhen,values)) as f}<dt>{f.label}</dt><dd>{display(fieldValue(f,values)??f.unavailable)}</dd>{/each}</dl>{#if section.collection&&matches(section.collection.when,values)}{#each quote?.collections[section.collection.key]??[] as entry,i}<h4>{section.collection.label} {i+1}</h4><dl>{#each section.collection.fields as f}<dt>{f.label}</dt><dd>{display(fieldValue(f,{...values,...entry},i)??f.unavailable)}</dd>{/each}</dl>{/each}{/if}<button class="btn sm" disabled={busy} onclick={()=>navigate(section)}>Edit {section.title.toLowerCase()}</button></details>
      {/each}
     {/if}
     <div class="form-actions">{#if quote&&step>0}<button class="btn" disabled={busy} onclick={()=>navigate(journey[step-1])}>← Back</button>{/if}<span class="spacer"></span>{#if pageID==='review'}<button class="btn primary" disabled={busy||!eligible||quote?.status==='ready_for_rating'} onclick={submit}>{busy?'Submitting…':quote?.status==='ready_for_rating'?'Submitted for rating':'Submit application for rating'}</button>{:else}{#if quote}<button class="btn" disabled={busy} onclick={()=>save(false)}>{busy?'Saving…':'Save draft'}</button>{/if}<button class="btn primary" disabled={busy} onclick={()=>save(true)}>{busy?'Saving…':creating?'Create quote & continue':'Save & continue →'}</button>{/if}</div>
    </section>
    <p class="footer-note">Your quote is stored on this computer. Rating, CLUE, payment processing and policy binding require carrier integrations.</p>
   </div>
   <QuoteSidebar {values} {quote} coapplicants={pageID==='account'?rows:quote?.collections.coapplicants??[]}/>
  </div>
 {/if}
</div>
<style>
 .source-actions,.service-panel{border:1px solid var(--border);border-radius:7px;padding:16px;margin-top:18px}.source-actions>div{display:flex;flex-wrap:wrap;gap:14px}.source-action{display:grid;align-content:start;gap:6px;max-width:220px}.source-action small{font-size:11px;color:var(--text-muted);line-height:1.4}.service-panel summary,.row-details summary{font-size:13px;font-weight:600;cursor:pointer;margin-bottom:12px}.service-buttons{display:flex;flex-wrap:wrap;gap:8px}

 .application{max-width:1680px;margin:auto}.breadcrumb{font-size:12px;color:var(--text-muted);display:flex;gap:9px;margin:0 0 20px}.breadcrumb span{color:var(--text-faint)}.application-header{display:flex;justify-content:space-between;align-items:center;gap:20px;margin:0 0 22px}.eyebrow{font-size:10px;font-weight:600;letter-spacing:.8px;color:var(--text-muted)}h1{font-size:24px;margin:5px 0 7px}h2{font-size:17px;margin:0}h3{font-size:14px;margin:0 0 12px}p{line-height:1.6;font-size:13px}.header-actions{display:flex;gap:12px;align-items:center}.status{font-size:11px;font-weight:500;background:var(--surface-3);color:var(--text-muted);padding:3px 8px;border-radius:20px;white-space:nowrap}.status.ready{background:var(--success-soft);color:var(--success)}.workspace-split,.quote-layout{display:grid;grid-template-columns:minmax(0,7fr) minmax(0,3fr);gap:22px;align-items:start}.quote-body{min-width:0}.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin-bottom:22px}.metric,.overview-item{display:flex;align-items:center;gap:12px;background:var(--surface);border:1px solid var(--border);border-radius:9px;padding:16px}.metric>div{display:flex;align-items:center;justify-content:space-between;flex:1;gap:8px}.metric small{font-size:13px;font-weight:600}.metric strong{font-size:24px}.metric-icon,.section-icon{display:grid;place-items:center;background:var(--accent-soft);color:var(--accent);border-radius:5px;padding:7px;flex-shrink:0}.metric-icon.green{background:var(--success-soft);color:var(--success)}.dashboard-card{background:var(--surface);border:1px solid var(--border);border-radius:10px;box-shadow:0 2px 4px #18244004;overflow:hidden}.panel-heading{display:flex;justify-content:space-between;align-items:center;gap:16px;padding:18px;border-bottom:1px solid var(--border)}.panel-heading h2{display:flex;align-items:center;gap:9px;font-size:15px}.panel-heading p{font-size:12px;margin-top:4px}.search{display:flex;align-items:center;gap:6px;border:1px solid var(--border);border-radius:6px;padding:0 9px;max-width:230px}.search input{border:0;background:none;min-width:0;width:100%;font-size:12px;padding:8px 0}.filters{display:flex;gap:5px;padding:4px;background:var(--surface-2);border:1px solid var(--border);margin:16px;border-radius:6px;flex-wrap:wrap}.filters button{border:0;border-radius:5px;background:var(--surface);color:var(--text-muted);font:500 12px var(--font);padding:8px 12px;display:flex;gap:10px;cursor:pointer}.filters button.active{background:var(--accent);color:var(--accent-text)}.filters button span{opacity:.75}.quote-table{overflow-x:auto;padding:0 16px;min-height:330px}.quote-table table{font-size:12px}.quote-table th{background:var(--surface);text-transform:none;letter-spacing:0;font-size:11px;padding:12px 8px;white-space:nowrap}.quote-table td{vertical-align:middle;padding:17px 8px;white-space:nowrap}.quote-table td strong{font-weight:500}.quote-table td small{display:block;color:var(--text-muted);font-size:10px;margin-top:5px}.quote-link{background:none;border:0;color:var(--accent);font:600 12px var(--font);cursor:pointer;padding:0}.form-badge{border:1px solid var(--border);padding:2px 8px;border-radius:20px;font-size:11px}.open-quote{display:grid;place-items:center;border:1px solid var(--border);background:var(--surface);border-radius:5px;color:var(--accent);padding:5px;cursor:pointer}.table-footer{padding:14px 20px;border-top:1px solid var(--border);color:var(--text-muted);font-size:11px}.dashboard-aside{display:grid;gap:18px}.queue{padding:12px;display:grid;gap:10px}.queue button{text-align:left;border:1px solid var(--border);border-radius:7px;background:var(--surface);color:var(--text);padding:12px;cursor:pointer;font:inherit}.queue button:hover{border-color:var(--accent)}.queue button>div{display:flex;align-items:center;justify-content:space-between;gap:8px}.queue strong{font-size:12px}.queue p{font-size:11px;color:var(--text-muted);margin:4px 0 12px}.queue-footer{border-top:1px solid var(--border);paddi